import re
from pathlib import Path

here = Path(__file__).parent
old = (here.parent / 'concept-deck/build.mjs').read_text(encoding='utf-8-sig')
main = (here / 'main.mjs').read_text(encoding='utf-8-sig')
prefix, body = old.split('// The opening works as a short, self-contained reading path.\n', 1)
sections, footer = body.split('for (let i=0;i<registry.length;i++){', 1)
blocks = {re.search(r'slide\("([^"]+)', part)[1]: '{\n'+part for part in sections.split('{\n  const s=slide(')[1:] for part in ['  const s=slide('+part]}
cover = blocks['cover'].replace('Как учитель превращает результаты\\nработы в следующий учебный шаг','Как учитель готовит работу по алгебре\\nи решает, что повторить с классом').replace('Рабочая концепция   /   8 ноября 2026','Продуктовая концепция   /   версия 2')
main, map_slide = main.split('{\n  const s=slide("map"', 1)
homework = blocks['variants'].replace('"variants"', '"homework"').replace('["Как выбираем повторение","next"],["Выдача и ключ","paper"]','["Что дать после проверки","next"],["Как готовится работа","prepare"]').replace('Учитель видит общий объём. Пересекающиеся назначения требуют проверки на повторы.','Перед печатью учитель смотрит общий объём и убирает повторяющиеся задания.')
replacements = {
'working': [('Работающая основа продукта','Что уже можно открыть и использовать'),('Обычные задания, варианты с ответами и настройки усложнений.','Генератор создаёт задания и варианты. Их можно сохранить в PDF и распечатать.')],
'practice': [('Учебная попытка','Упражнение в браузере'),('Бумажный цикл учителя показан в отдельном разделе.','На уроке из примера класс работает на бумаге.')],
'value': [('Подготовка, проверка и помощь','На что у учителя уходит время'),('Разный уровень','Составить варианты'),('Учитель подбирает работу по общей цели класса и меняет опоры или объём для отдельных учеников.','Учителю нужны разные листы по одному умению, иногда с подсказкой или меньшим числом заданий.'),('Долгая проверка','Сверить ответы'),('Выбор следующего шага','Понять, что повторить')],
'method': [('Умение, шаблон и усложнение','Как из одного умения получается много задач'),('Числа и буквы в примерах меняются, а проверяемое действие сохраняется.','6x + 9 и 8y + 12 проверяют одно действие. Меняются числа и буквы. Для каждого примера формируется свой ответ.'),('Проверка переноса','Новая задача'),('После практики ученик выполняет свежую задачу с уместным изменением записи или сочетанием освоенных действий.','После практики учитель может дать пример с вычитанием и посмотреть, применит ли ученик тот же способ.')],
'example': [('Что может стоять за ошибкой','Как учитель разбирает неверный ответ'),('После разбора — новый пример на то же действие.','Для повторной проверки учитель даёт 10a + 15.')],
'scope': [('Границы MVP','Что обсуждаем для первого платного выпуска'),('Модель для обсуждения','Целевой сценарий'),('Подбор, выдача, получение ответов и сводка составляют один учительский цикл. Конкретный состав первого выпуска уточняется.','Учитель печатает работу, получает ответы и видит сводку. Какие части войдут в платный выпуск, ещё уточняем.')],
'model': [('Данные одного учебного цикла','Как связаны лист, ключ и ответ'),('Выданная работа','Конкретный лист'),('Попытка относится к конкретному заданию. Заметка фиксирует то, что учитель увидел на уроке.','Пример: ученик с вариантом А отметил Б в задании № 2. Сервис сверяет эту отметку с ключом именно варианта А.'),('Общая история питает представления урока и ученика. Учитель выбирает последующую практику.','Результаты отдельных учеников складываются в сводку класса. Учитель может открыть ответы по конкретному заданию.')],
'pilot': [('Первый сквозной прогон','Что проверим на одном реальном уроке'),('Проверяем самостоятельный выбор и печать. Рабочий ориентир для короткой работы — до 10 минут до PDF.','Учитель сам собирает короткую работу. Замеряем время от выбора темы до готового PDF. Ориентир — до 10 минут.'),('Сверяем прочитанные ответы с листами и разбираем исключения. Рабочий ориентир — до 30 минут от первого фото до сводки.','Сверяем прочитанные ответы с оригиналами. Замеряем время от первого фото до сводки. Ориентир — до 30 минут.')],
'client': [('Подберите задания под нужное умение и подготовьте разные варианты для класса.','Соберите работу по нужному умению и распечатайте разные варианты для класса.'),('В проектируемом цикле результаты бумажной работы помогут выбрать, что повторить всему классу и кому дать отдельное задание.','Следующая цель продукта — собрать результаты бумажных работ и показать, в каких заданиях ошиблись ученики.')],
}
for key, pairs in replacements.items():
    for before, after in pairs:
        assert before in blocks[key], before
        blocks[key] = blocks[key].replace(before, after)

order = ['value','usp','method','example','absence','scope','model','pilot','team','decisions','client','sources']
output = prefix + cover + main + blocks['working'] + blocks['practice'] + '{\n  const s=slide("map"' + map_slide + homework
output += ''.join(blocks[key] for key in order)
output += 'for (let i=0;i<registry.length;i++){' + footer
output = output.replace('["История ученика","results"]','["Пример сводки класса","results"]').replace('403+j*275,649,260,39','403+j*320,649,306,39')
(here / 'build.mjs').write_text(output,encoding='utf-8')
